tool_input.command:
cd <repo>
python3 - <<'EOF'
path = "internal/hook/pretooluse_dispatch.go"
src = open(path).read()
old = '''	if missionID := os.Getenv("MISSION_ID"); missionID != "" {
		return dispatchTierB(w, sessionID, missionID, toolInput, mission.BoundViaMissionIDEnv,
			func() { consumeDispatchBinding(sessionID, missionID) })
	}'''
new = '''	if missionID := os.Getenv("MISSION_ID"); missionID != "" {
		return dispatchTierB(w, sessionID, missionID, toolInput, mission.BoundViaMissionIDEnv, nil)
	}'''
assert old in src
open(path, "w").write(src.replace(old, new, 1))
EOF
go test ./internal/hook/... -run 'TestDispatchAgent_ExplicitMissionIDConsumesMatchingPendingEntry' -v -count=1 2>&1 | tail -30

